\begin{algorithm}
\caption{Simple randomized approximation heuristic for UD-MIS}\label{alg:ptas}
\begin{flushleft}
\textbf{Input:} a unit-disk graph $G=(V,E)$. 

\textbf{Output:} a bit assignment for every vertex ($\{b_{v}\}_{v\in V}$), coding for an independent set.

\textbf{Output:} a bit assignment for every vertex ($\{b_{v}\}_{v\in V}$), coding for an independent set.

\textbf{Execution parameter:} An integer $d\geq0$. 
\end{flushleft}
\begin{algorithmic}[1]
\State $B \leftarrow \emptyset$ \Comment{$B$ will contain the ``border'' between exactly-solved patches}
\State $W = V$
\State 
\While{$W\neq \emptyset$}{
\State Pick a vertex $u\in W$ randomly.
\State Compute $S_{d}(u)$, the set of vertices within distance $d$ of $u$ in $G\left[W\right]$ using e.g. Breadth-First Search.
\State Compute bit assignment = solve MIS exactly for $G[S_{d}(u)]$.
\State let $C_{u,d}= \left\{v\in \left[W\setminus S_{d}(u)\right]\text{ s.t } b_{v}\text{ is \emph{constrained} to be 0}  \right\}$
\State $B \leftarrow B\cup C_{u,d} $
\State $W \leftarrow W\setminus S_{d}(u)$
\State $W \leftarrow W\setminus C_{u,d}$
}
\end{algorithmic}
\end{algorithm}

