To this aim, we then compute the following binned correlation function
\begin{equation}
	g^{(2)}(r) = \max_{\substack{G\in \mathcal{G}\\i,j\\
|\boldsymbol{r}_{i}-\boldsymbol{r}_{j}|\approx r
}
}|\langle z_{i}z_{j}\rangle_{\rho_G}|
\label{eq:g2_def}
\end{equation}


We thus extract the envelope by finding, for each bin around $r$, the maximum over several (here 5) random graph instances, and over all pairs such that $|\boldsymbol{r}_{i}-\boldsymbol{r}_{j}|$ is in the vicinity $\delta r$ of $r$ (here, we choose $\delta r = 0.04$, but the results do not depend on this value provided each bin $\delta r$ around $r$ contains enough points).
Similar (although quantitatively slightly different) results can be obtained by averaging over the bin, instead of maximizing.


We plot the corresponding curves in Fig.~\ref{fig:corr_func_vs_distance}. An exponential fit $\exp(-r/\xi(\gamma, N_\mathrm{atoms}))$ turns out to be an accurate description of the data. We extract the corresponding correlation length $\xi$, which we plot in Fig.~\ref{fig:xi_vs_natoms}.

We want to compute the expectation value $M(N)$ of the maximum of the value of
$-H_{\mathrm{target}}$ over $N$ repetitions of the preparation and
measurement of $\Psi$ ($N=n_\mathrm{shots}$ in the main text). It is given by:
\begin{align}
M(N) & \equiv\mathbb{E}_{P}\left[\max\left(E_{i_{1}},\dots,E_{i_{N}}\right)\right] \\
& = \sum_{i_{1}\dots i_{N}}\max\left(E_{i_{1}},\dots,E_{i_{N}}\right)P\left(i_{1},i_{2}\dots i_{N}\right)\label{eq:M_N_def}
\end{align}

where $P\left(i_{1},i_{2}\dots i_{N}\right)$ is the probability of
observing the states $i_{1},\dots i_{N}$ as the $N$ outcomes of the
readouts. Since the repetitions are independent, 
$P\left(i_{1},i_{2}\dots i_{N}\right)=p_{i_{1}}\dots p_{i_{N}}$
and thus
\begin{equation}
    M(N)=\sum_{i_{1}\dots i_{N}}\max\left(E_{i_{1}},\dots,E_{i_{N}}\right)p_{i_{1}}\dots p_{i_{N}}\label{eq:M_N_expr}
\end{equation}

We note that
\[
M(N=1)=\langle E\rangle_{p}
\]

Furthermore, denoting by $E_{\mathrm{max}}$ the maximum target energy,
we expect that, if the support of $p$ contains the state with maximum
energy (the MIS),

\begin{align*}
M(N=\infty) & =E_{\mathrm{max}}.
\end{align*}


\subsection{Computation using the density of states}

We now define the following "target" density of states:
\begin{equation}
D(\varepsilon)\equiv\sum_{i=0}^{2^{n}-1}p_{i}\delta(\varepsilon-E_{i})\label{eq:dos_def}
\end{equation}

Let us call $\mathcal{F}_{N}$ the cumulative distribution function
(CDF) of $\mathcal{E}_{N}$.
Then:

\begin{align}
M(N)  &=\mathbb{E}_{R_{N}}\nonumber\\
&=\int_{E_{\mathrm{\text{min}}}}^{E_{\mathrm{max}}}\varepsilon\mathcal{F}_{N}'(\varepsilon)d\varepsilon\nonumber\\
 & =\left[\varepsilon\mathcal{F}_{N}(\varepsilon)\right]_{E_{\mathrm{min}}}^{E_{\mathrm{max}}}-\int_{E_{\mathrm{min}}}^{E_{\mathrm{max}}}\mathcal{F}_{N}(\varepsilon)d\varepsilon \label{eq:M_N_interm}
\end{align}
where we have used integration by parts to obtain the last line.

We can now simplify the expression for $\mathcal{F}_{N}$. Let us denote by $F$ the CDF corresponding to the probability distribution function $D$,
i.e $D=F'$. Then
\begin{align*}
\mathcal{F}_{N}(\varepsilon) & =P\left(\max\left(\varepsilon_{1},\dots,\varepsilon_{N}\right)\leq\varepsilon\right)\\
 & =P(\varepsilon_{1}\leq\varepsilon,\dots\varepsilon_{N}\leq\varepsilon)\\
 & =P(\varepsilon_{1}\leq\varepsilon)\dots P(\varepsilon_{N}\leq\varepsilon)\\
 & =\left[ F(\varepsilon) \right]^N
\end{align*}

We thus obtain the final expression:
\begin{equation}
 M(N) =E_{\mathrm{max}}-\int_{E_{\mathrm{min}}}^{E_{\mathrm{max}}}\left[ F(\varepsilon) \right]^Nd\varepsilon\label{eq:M_N_final}
\end{equation}

Since $F(\varepsilon)<1 (\forall\varepsilon\in]E_{\mathrm{min}},E_{\mathrm{max}}[$),
we have, as expected:
\[
M(N=\infty)=E_{\mathrm{max}}
\]

